extension HealthGuides {
    static let dentalCare = DirectoryGuide(
        cardSummary: .init(ukrainian: "Касовий стоматолог, біль, пломби та кошторис перед дорогим лікуванням", german: "Kassenzahnarzt, Schmerzen, Füllungen und Kostenvoranschlag"),
        introduction: .init(ukrainian: "Покриття стоматології залежить від послуги та страховика. Складні роботи не варто погоджувати без плану лікування й письмової ціни.", german: "Die Deckung der Zahnbehandlung hängt von Leistung und Kasse ab. Größere Arbeiten erst nach Behandlungsplan und schriftlicher Kostenauskunft zusagen."),
        sections: [
            .init("find", "tooth", "Знайдіть стоматолога", "Zahnbehandlung finden", "Шукайте Vertragszahnarzt із договором саме вашої каси або Zahngesundheitszentrum ÖGK у своїй землі. При гострому болю телефонуйте в центр чи чергову службу; 1450 допоможе зорієнтуватися поза звичайним часом. З’ясуйте, чи приймають зараз і чи потрібен запис.", "Suchen Sie einen Vertragszahnarzt Ihrer Kasse oder ein ÖGK-Zahngesundheitszentrum im Bundesland. Bei akuten Schmerzen rufen Sie Zentrum oder Bereitschaftsdienst an; außerhalb der Öffnungszeiten hilft 1450 bei der Orientierung. Fragen Sie nach Aufnahme und Termin.", source: dental),
            .init("coverage", "eurosign.circle", "Що покриває каса", "Was die Kasse zahlt", "Базові договірні стоматологічні послуги можуть розраховуватися через e-card; матеріал пломби, протезування, імплантати й естетичні рішення мають окремі правила, внески або приватну оплату. Перед лікуванням попросіть назвати касовий варіант, доплату й альтернативи, а для великої роботи — Heil- und Kostenplan та можливе погодження страховика.", "Vertragliche Grundleistungen können über die e-card abgerechnet werden. Füllungsmaterial, Zahnersatz, Implantate und ästhetische Lösungen haben eigene Regeln, Selbstbehalte oder Privatkosten. Fragen Sie vorab nach Kassenvariante, Aufpreis und Alternativen; bei größeren Arbeiten nach Heil- und Kostenplan sowie nötiger Kassenbewilligung.", source: dental),
            .init("private", "doc.text", "Якщо лікування приватне", "Bei privater Behandlung", "Попросіть деталізований кошторис до початку, збережіть рахунок і підтвердження оплати. До оплати уточніть у своєї каси, чи можливе й у якому розмірі відшкодування. Не вважайте, що будь-який приватний рахунок автоматично відшкодовується.", "Lassen Sie sich vor Beginn einen detaillierten Kostenvoranschlag geben und bewahren Sie Rechnung und Zahlungsnachweis auf. Fragen Sie Ihre Kasse vorab, ob und in welcher Höhe eine Erstattung möglich ist. Eine Privatrechnung wird nicht automatisch ersetzt.", source: dental),
            .init("children", "figure.child", "Дитина й профілактика", "Kinder und Vorsorge", "Запишіть дитину на огляд і уточніть у касового стоматолога профілактику, лікування та можливі витрати на ортодонтію. Окремі дитячі програми й виплати залежать від віку та медичних критеріїв — перевіряйте до підписання приватної пропозиції.", "Vereinbaren Sie einen Kontrolltermin für Ihr Kind und klären Sie Vorsorge, Behandlung und mögliche Kosten einer Zahnregulierung. Kinderleistungen hängen von Alter und medizinischen Kriterien ab; vor einer Privatvereinbarung prüfen.", source: dental)
